import {DEPARTMENTS,SYSTEM_ROLES,USERS} from './data/demo-data.js';
import {store} from './state/store.js';
import {STATUS,PRIORITY,SHIFT} from './types.js';
import {elapsedMs,formatDuration,actualMinutes} from './utils/timer.js';
import {metrics} from './utils/metrics.js';
import {icon,avatar,button,statusChip,priorityChip,progressBar,sectionTitle,emptyState,openModal,showToast} from './ui.js?v=23';
import {recipeRepository} from './repositories/recipe-repository.js?v=22';
import {recipeEditorialPanel} from './recipes/recipe-editorial-ui.js?v=21';
import {inventoryRepository} from './repositories/inventory-repository.js?v=23';
import {inventoryDashboard,inventoryMovementForm} from './inventory/inventory-ui.js?v=23';
import {productionOrderRepository} from './repositories/production-order-repository.js?v=30';
import {productionOrderList,productionOrderDetail as liveProductionOrderDetail} from './production/production-order-ui.js?v=27';
import {can} from './permissions.js';
import {readDocx} from './import/docx-reader.js';
import {parseRecipeBlocks} from './import/recipe-parser.js';
import {DEMO_PRODUCTIONS,createDemoProductionPhases} from './data/demo-production-plan.js';
import {blockedBy,buildProductionPlan,canStartPhase,formatClock} from './production/production-engine.js';
import {createDemoProductionOrders} from './data/demo-production-orders.js';
import {ORDER_STATUSES,advanceOrder,canAdvanceOrder,currentChecklist,nextOrderStatus,orderProgress,orderStatus} from './production/production-order-model.js';
import {DEMO_INTERMEDIATE_BATCHES,DEMO_INVENTORY_ITEMS,createDemoInventoryEvents} from './data/demo-inventory.js';
import {EVENT_TYPES,INVENTORY_TYPES,inventoryAlerts,projectInventory,registerInventoryEvent,yieldVariance} from './inventory/inventory-engine.js';
import {DEMO_CASH_MOVEMENTS,DEMO_COST_COMPONENTS,DEMO_MANAGEMENT_CONTEXT,DEMO_SALES} from './data/demo-management.js';
import {abcCost,cashProjection,managementKpis,miskiReply,purchaseRecommendations} from './finance/management-engine.js';
import {authenticatedUser,onPasswordRecovery,requestPasswordRecovery,signIn,signOut,updatePassword} from './auth/supabase-auth.js';

const app=document.querySelector('#app');
let route='home',sessionUser=null,authReady=false,authBusy=false,authMessage='',passwordRecovery=false,selectedTask=null,selectedRecipe=null,selectedProductionOrder=null,recipeSearch='',recipeCategory='',inventoryType='',miskiMessages=[{role:'miski',text:'Hola, soy Miski. Puedo ayudarte a entender la operación de hoy.'}],importedDrafts=[],selectedImportIndex=0,importBusy=false,productionPhases=createDemoProductionPhases(),productionOrders=createDemoProductionOrders(),inventoryEvents=createDemoInventoryEvents(),filters={assignee:'',shift:'',status:'',priority:''};
app.addEventListener('click',event=>{const typeButton=event.target.closest('[data-inventory-type]');if(!typeButton)return;inventoryType=typeButton.dataset.inventoryType;render()});
app.addEventListener('submit',async event=>{if(event.target.id!=='inventoryEventForm')return;event.preventDefault();const submit=event.target.querySelector('[type="submit"]'),form=new FormData(event.target);submit.disabled=true;try{await inventoryRepository.register({itemId:form.get('itemId'),type:form.get('eventType'),quantity:form.get('quantity'),productionOrderId:form.get('productionOrderId'),reference:form.get('reference')?.trim(),notes:form.get('note')?.trim()});route='inventory';showToast('Movimiento guardado. El stock fue recalculado desde Supabase.');render()}catch(error){showToast(error.message||'No pudimos registrar el movimiento.','error');submit.disabled=false}});
app.addEventListener('change',async event=>{if(!event.target.matches('[data-inventory-order]'))return;try{await inventoryRepository.selectOrder(event.target.value);render()}catch(error){showToast(error.message||'No pudimos calcular la comparación.','error')}});
app.addEventListener('click',async event=>{const open=event.target.closest('[data-live-production-order]'),action=event.target.closest('[data-op-action]');if(open){selectedProductionOrder=open.dataset.liveProductionOrder;route='productionOrderDetail';render();try{await productionOrderRepository.loadDetail(selectedProductionOrder);render()}catch(error){showToast(error.message||'No pudimos abrir la OP.','error')}return}if(action){action.disabled=true;try{await productionOrderRepository.transition(selectedProductionOrder,action.dataset.opAction);showToast('La OP quedó actualizada y auditada.');render()}catch(error){showToast(error.message||'No pudimos actualizar la OP.','error');action.disabled=false}}});
document.addEventListener('click',async event=>{const manjar=event.target.closest('[data-task="demo-manjar"]');if(!manjar||sessionUser?.role!=='admin')return;event.preventDefault();event.stopImmediatePropagation();manjar.disabled=true;await openManjarProductionOrder()},true);
app.addEventListener('submit',async event=>{if(!['opUsageForm','opFinishForm'].includes(event.target.id))return;event.preventDefault();const form=new FormData(event.target),submit=event.target.querySelector('[type="submit"]');submit.disabled=true;try{if(event.target.id==='opUsageForm'){await productionOrderRepository.registerUsage(selectedProductionOrder,{itemId:form.get('itemId'),type:form.get('usageType'),quantity:form.get('quantity'),notes:form.get('notes')?.trim()});showToast('Movimiento registrado. Inventario y desviación fueron recalculados.')}else{await productionOrderRepository.transition(selectedProductionOrder,'FINISH',{actualQuantity:Number(form.get('actualQuantity')),observation:form.get('observation')?.trim()});showToast('Excelente trabajo. La OP quedó finalizada.')}render()}catch(error){showToast(error.message||'No pudimos guardar el registro.','error');submit.disabled=false}});
app.addEventListener('submit',event=>{if(event.target.id!=='miskiManagementForm')return;event.preventDefault();const form=new FormData(event.target),message=form.get('message')?.trim();if(!message)return;const purchase=purchaseRecommendations(DEMO_INVENTORY_ITEMS,inventoryEvents)[0]||{message:'Los niveles actuales no requieren una compra inmediata.'};miskiMessages.push({role:'user',text:message},{role:'miski',text:miskiReply(message,{...DEMO_MANAGEMENT_CONTEXT,purchase})});render()});
const userById=id=>sessionUser?.id===id?sessionUser:USERS.find(u=>u.id===id);
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const today=()=>{const value=new Intl.DateTimeFormat('es-PE',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date());return value.charAt(0).toUpperCase()+value.slice(1)};
const clock=i=>i?new Intl.DateTimeFormat('es-PE',{hour:'2-digit',minute:'2-digit'}).format(new Date(i)):'—';
const uid=()=>globalThis.crypto?.randomUUID?.()||`task-${Date.now()}`;
const go=async(next,id=null)=>{route=next;selectedTask=id;render();scrollTo({top:0,behavior:'smooth'});if(next==='recipes'&&sessionUser?.role==='admin'&&!recipeRepository.loaded){try{await recipeRepository.load();render()}catch(error){showToast(error.message||'No pudimos abrir el recetario privado.','error')}}if((next==='inventory'||next==='inventoryEvent')&&sessionUser?.role==='admin'&&!inventoryRepository.loaded){try{await inventoryRepository.load();render()}catch(error){showToast(error.message||'No pudimos abrir el inventario privado.','error')}}if(next==='productionOrders'&&sessionUser?.role==='admin'&&!productionOrderRepository.loaded){try{await productionOrderRepository.load();render()}catch(error){showToast(error.message||'No pudimos abrir las órdenes.','error')}}};
const HUMAN_STATUS={pending:'Por comenzar',ready:'Todo listo',in_progress:'En marcha',paused:'Tomamos una pausa',completed:'Completada',incident:'Necesita atención'};
const plural=(n,one,many)=>n===1?one:many;
const miskiPrompt=()=>`<aside class="miski-prompt" aria-label="Miski, futura asistente de Le Miski OS"><span class="miski-orb" aria-hidden="true">✦</span><div><span class="eyebrow">Miski · Próximamente</span><strong>¿Necesitas ayuda?</strong><p>Muy pronto podrás preguntarme cómo organizar tu jornada.</p></div><div class="miski-future" aria-disabled="true">Pregunta a Miski ${icon('spark',16)}</div></aside>`;

function access(){return `<main class="access" id="main-content"><section class="access-brand"><div class="wordmark">Le Miski<small>El ritmo de nuestra cocina</small></div><div><span class="prototype">Un espacio para trabajar con calma</span><h1>Tu jornada, clara desde el comienzo.</h1><p>Le Miski OS acompaña cada preparación para que el equipo sepa qué sigue y pueda concentrarse en hacerlo extraordinario.</p></div><small>Uso interno · Le Miski</small></section><section class="access-panel"><span class="eyebrow">Acceso protegido</span><h2>Bienvenida a Le Miski OS</h2><p class="muted">Ingresa con tu cuenta personal. Tus permisos se validan de forma segura.</p><form id="authForm"><label class="field"><span>Correo</span><input name="email" type="email" autocomplete="username" required></label><label class="field"><span>Contraseña</span><input name="password" type="password" autocomplete="current-password" required></label>${authMessage?`<div class="alert">${icon('alert')}<span>${esc(authMessage)}</span></div>`:''}<div class="form-actions">${button({label:'Olvidé mi contraseña',variant:'tertiary',type:'button',attrs:'data-forgot-password'})}${button({label:authBusy?'Ingresando…':'Ingresar',iconName:'arrow',type:'submit',attrs:authBusy?'disabled aria-busy="true"':''})}</div></form><p class="field-hint">La recuperación por correo se activará al configurar la URL definitiva de Vercel.</p></section></main>`}

function nav(user){const links=[['home','home','Hoy'],['board','production','La jornada'],...(can(user,'recipes')?[['recipes','book','Recetas']]:[]),...(user.role==='admin'?[['inventory','inventory','Inventario']]:[]),['summary','summary','Cómo nos fue'],['more','more','Tu espacio']];const isActive=r=>route===r||(r==='recipes'&&['recipeDetail','recipeImport','recipeReview'].includes(route))||(r==='inventory'&&route==='inventoryEvent');const items=links.map(([r,i,l])=>`<button class="nav-item ${isActive(r)?'active':''}" data-route="${r}" aria-current="${isActive(r)?'page':'false'}">${icon(i)}<span class="nav-label">${l}</span></button>`).join('');return `<aside class="sidebar" aria-label="Navegación principal"><div class="wordmark">Le Miski<small>Trabajemos con calma</small></div><nav class="side-nav">${items}</nav><div class="side-user">${avatar(user.name,'sm')}<div class="side-user-copy"><strong>${esc(user.name)}</strong><small>${esc(DEPARTMENTS[user.area])} · ${esc(SYSTEM_ROLES[user.role])}</small></div><button class="icon-button" data-logout aria-label="Cerrar sesión">${icon('logout')}</button></div></aside><nav class="bottom-nav ${links.length===6?'bottom-nav-six':can(user,'recipes')?'bottom-nav-five':''}" aria-label="Navegación principal">${items}</nav>`}
function shell(content,user){return `<div class="shell">${nav(user)}<main class="main" id="main-content">${content}</main></div>`}
function pageHeader(eyebrow,title,copy='',action=''){const contextual=title==='Motor de Producción'?button({label:'Órdenes de producción',variant:'secondary',attrs:'data-route="productionOrders"'}):title==='Órdenes de Producción'?button({label:'Inventario inteligente',variant:'secondary',attrs:'data-route="inventory"'}):title==='Inventario Inteligente'?button({label:'Vista gerencial',variant:'secondary',attrs:'data-route="management"'}):title==='Recetas de Le Miski'?button({label:'Crear receta',variant:'secondary',attrs:'data-manual-recipe'}):'';return `<header class="page-header"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${copy?`<div class="date">${copy}</div>`:''}</div><div class="header-actions">${contextual}${action}</div></header>`}
function metricCard(label,value,iconName,detail=''){return `<article class="metric"><span class="metric-icon">${icon(iconName,17)}</span><span>${label}</span><strong>${value}</strong>${detail?`<small>${detail}</small>`:''}</article>`}

function taskCard(t,admin=false){const u=userById(t.assigneeId),value=t.status==='completed'?100:t.progress||0;return `<article class="task-card priority-${t.priority}" style="animation-delay:${Math.min(4,store.get().tasks.indexOf(t))*.045}s"><div class="task-top"><div><span class="eyebrow">${esc(t.plannedTime)} · ${SHIFT[t.shift]}</span><h3>${esc(t.preparation)}</h3></div>${statusChip(t.status,HUMAN_STATUS[t.status])}</div><div class="badges">${priorityChip(t.priority,PRIORITY[t.priority])}<span class="chip">${avatar(u?.name||'','sm')}${esc(u?.name)}</span>${t.incident.reported?statusChip('incident','Revisemos esto'):''}</div><div class="task-meta"><div><small>Vamos a preparar</small><b>${esc(t.quantity)}</b></div><div><small>Tiempo estimado</small><b>${t.expectedMinutes} min</b></div><div><small>Buscamos obtener</small><b>${t.expectedYield.value} ${esc(t.expectedYield.unit)}</b></div>${t.timing.startedAt?`<div><small>Tiempo transcurrido</small><b>${actualMinutes(t)} min</b></div>`:''}${t.actualYield.value!==null?`<div><small>Lo que logramos</small><b>${t.actualYield.value} ${esc(t.actualYield.unit)}</b></div>`:''}</div>${progressBar(value,`Avance de ${esc(t.preparation)}`)}<div class="task-actions">${button({label:admin?'Ver cómo va':t.status==='pending'?'Prepararme':'Continuar',variant:admin?'secondary':'primary',iconName:'arrow',attrs:`data-task="${t.id}"`})}</div></article>`}

function adminHome(tasks){const m=metrics(tasks),workers=USERS.filter(u=>u.role==='production'),alerts=tasks.filter(t=>t.incident.reported||t.priority==='urgent'),next=tasks.filter(t=>t.status!=='completed').sort((a,b)=>a.plannedTime.localeCompare(b.plannedTime));const dayLine=m.completed===m.total&&m.total?'El equipo completó todo lo que habíamos planeado.':m.active?`${plural(m.active,'Hay una preparación en marcha.',`Hay ${m.active} preparaciones en marcha.`)}`:`Hoy acompañaremos ${m.total} ${plural(m.total,'preparación','preparaciones')}.`;return `${pageHeader('Hoy en Le Miski','Buenos días, Marisol.',today(),button({label:'Agregar preparación',iconName:'plus',attrs:'data-route="create"'}))}${miskiPrompt()}<section class="dashboard-grid"><article class="card overview-card"><div class="overview-top"><div><span class="prototype">Así comienza el día</span><h2>${dayLine}</h2><p>${next[0]?`La primera será ${esc(next[0].preparation)}, a las ${esc(next[0].plannedTime)}.`:'Podemos tomarnos un momento para revisar los resultados.'}</p></div><strong class="overview-percent">${m.progress}%</strong></div>${progressBar(m.progress,'Cómo avanza la jornada')}<div class="overview-meta"><div><small>Tiempo que reservamos</small><strong>${m.expectedMinutes} min</strong></div><div><small>Ahora mismo</small><strong>${m.active?`${m.active} en marcha`:'Todo en calma'}</strong></div><div><small>Para revisar</small><strong>${m.incidents||'Nada'}</strong></div></div></article><article class="card attention-card"><div class="attention-head"><h2>Lo que merece atención</h2>${statusChip(alerts.length?'incident':'completed',alerts.length?`${alerts.length} por revisar`:'Todo en calma')}</div><div class="attention-list">${alerts.length?alerts.slice(0,2).map(t=>`<button class="attention-item" data-task="${t.id}">${icon('alert')}<span><strong>${esc(t.preparation)}</strong><small>${t.incident.reported?'El equipo dejó una nota':'Conviene comenzar pronto'}</small></span></button>`).join(''):`<div class="attention-item">${icon('check')}<span><strong>No necesitas intervenir</strong><small>El equipo tiene claridad para continuar.</small></span></div>`}</div></article></section>${sectionTitle('Una mirada rápida','¿Cómo vamos?')}<section class="metric-grid">${metricCard('Preparaciones de hoy',m.total,'production','el plan completo')}${metricCard('Aún por hacer',m.pending,'clock','sin prisa, con orden')}${metricCard('Ya están listas',m.completed,'check','buen trabajo del equipo')}${metricCard('Pedidos de hoy','—','orders','lo conectaremos más adelante')}</section>${sectionTitle('Para seguir','¿Qué deseas hacer ahora?')}<section class="quick-actions"><button class="quick-action" data-route="create"><span class="quick-action-icon">${icon('plus')}</span><span><strong>Agregar una preparación</strong><small>Dar claridad al equipo</small></span></button><button class="quick-action" data-route="board"><span class="quick-action-icon">${icon('production')}</span><span><strong>Acompañar la jornada</strong><small>Ver cómo avanza cada persona</small></span></button><button class="quick-action" data-route="summary"><span class="quick-action-icon">${icon('summary')}</span><span><strong>Mirar el día completo</strong><small>Reconocer avances y aprendizajes</small></span></button></section>${sectionTitle('Las personas primero','¿Cómo está el equipo?')}<section class="team-list">${workers.map(w=>{const mine=tasks.filter(t=>t.assigneeId===w.id),active=mine.find(t=>t.status==='in_progress'),done=mine.filter(t=>t.status==='completed').length;return `<article class="card team-member">${avatar(w.name)}<div class="team-member-copy"><strong>${esc(w.name)}</strong><small>${active?`Está preparando ${esc(active.preparation)}`:done===mine.length&&mine.length?'Terminó su jornada':`Tiene ${mine.length-done} ${plural(mine.length-done,'preparación por hacer','preparaciones por hacer')}`}</small></div><span class="availability">${active?'Concentrada':'Lista'}</span></article>`}).join('')}</section>${sectionTitle('Lo que viene','Próximas preparaciones',button({label:'Ver la jornada',variant:'tertiary',iconName:'arrow',attrs:'data-route="board"'}))}<section class="cards">${next.length?next.slice(0,4).map(t=>taskCard(t,true)).join(''):emptyState('Todo está listo','El equipo completó la jornada. Es un buen momento para reconocer el trabajo.','check')}</section>`}

function workerHome(user,tasks){const mine=tasks.filter(t=>t.assigneeId===user.id),next=mine.find(t=>t.status!=='completed'),done=mine.filter(t=>t.status==='completed').length,remaining=mine.length-done;return `<section class="worker-header human-worker"><div><span class="prototype">${today()}</span><h1>Buenos días, ${esc(user.name)}.</h1><p>${remaining?`Hoy prepararemos ${remaining===1?'una producción':`${remaining} producciones`}. Iremos paso a paso.`:'Excelente trabajo. Todo lo de hoy está listo.'}</p></div><div class="next-task">${next?`<small>Comencemos por aquí</small><h2>${esc(next.preparation)}</h2><p>${esc(next.quantity)} · ${next.expectedMinutes} minutos</p>${button({label:next.timing.startedAt?'Continuar':'Prepararme',variant:'secondary',iconName:'arrow',attrs:`data-task="${next.id}"`})}`:'<small>Jornada completa</small><h2>Puedes sentirte orgullosa</h2><p>Gracias por cuidar cada detalle.</p>'}</div></section>${miskiPrompt()}<section class="human-progress card"><div><span class="eyebrow">Tu ritmo de hoy</span><h2>${done?`Ya completaste ${done} ${plural(done,'preparación','preparaciones')}.`:'Todo está listo para comenzar.'}</h2><p>${remaining?`Quedan ${remaining} ${plural(remaining,'preparación','preparaciones')}. No necesitas pensar en todas ahora; te mostraremos una a la vez.`:'La jornada está completa.'}</p></div><strong>${done}/${mine.length}</strong></section>${mine.some(t=>t.priority==='urgent'||t.incident.reported)?`<div class="alert">${icon('alert')}<span>Hay un detalle que conviene mirar antes de continuar. Si lo necesitas, Marisol puede acompañarte.</span></div>`:''}${sectionTitle('Tu camino de hoy','Después seguiremos con')}<section class="cards worker-cards">${mine.length?mine.map(t=>taskCard(t)).join(''):emptyState('Tu jornada está tranquila','Cuando haya una preparación para ti, aparecerá aquí con todo lo necesario.')}</section>`}

function createView(){return `${pageHeader('Preparemos el día','Agregar una preparación','Cuéntanos qué haremos, quién la acompañará y qué resultado esperamos.',button({label:'Volver a hoy',variant:'tertiary',attrs:'data-route="home"'}))}<form id="taskForm" class="panel"><div class="form-grid"><label class="field"><span>¿Qué vamos a preparar?</span><input name="preparation" required maxlength="80" placeholder="Ej. Ganache de chocolate"></label><label class="field"><span>¿Quién la preparará?</span><select name="assigneeId" required><option value="">Elige una persona</option>${USERS.filter(u=>u.role==='production').map(u=>`<option value="${u.id}">${u.name}</option>`).join('')}</select></label><label class="field"><span>¿En qué turno?</span><select name="shift" required><option value="morning">Mañana</option><option value="afternoon">Tarde</option></select></label><label class="field"><span>¿Cuánto prepararemos?</span><input name="quantity" required placeholder="Ej. 2 recetas"></label><label class="field"><span>¿A qué hora comenzamos?</span><input name="plannedTime" type="time" required></label><label class="field"><span>¿Cuánto tiempo reservamos?</span><input name="expectedMinutes" type="number" min="1" max="1440" required placeholder="Minutos"></label><label class="field"><span>¿Qué cantidad esperamos obtener?</span><input name="expectedValue" type="number" min="0" step="0.01" required></label><label class="field"><span>¿Cómo la mediremos?</span><select name="unit"><option>unidades</option><option>kg</option><option>g</option><option>litros</option><option>bandejas</option></select></label><label class="field"><span>¿Cuánta atención necesita?</span><select name="priority">${Object.entries(PRIORITY).map(([v,l])=>`<option value="${v}" ${v==='normal'?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>¿Cómo comienza?</span><select name="status">${Object.entries(STATUS).map(([v,l])=>`<option value="${v}" ${v==='pending'?'selected':''}>${HUMAN_STATUS[v]}</option>`).join('')}</select></label><label class="field full"><span>¿Qué debe tener presente?</span><textarea name="instructions" maxlength="300" required placeholder="Una indicación breve y clara para trabajar con confianza."></textarea><small class="field-hint">Comparte solo lo necesario para esta jornada. Las fórmulas maestras permanecen protegidas.</small></label></div><div class="form-actions">${button({label:'Ahora no',variant:'secondary',attrs:'data-route="home"'})}${button({label:'Dejarla preparada',iconName:'check',type:'submit'})}</div></form>`}

function board(tasks,user){const visible=user.role==='admin'?tasks:tasks.filter(t=>t.assigneeId===user.id),filtered=visible.filter(t=>(!filters.assignee||t.assigneeId===filters.assignee)&&(!filters.shift||t.shift===filters.shift)&&(!filters.status||t.status===filters.status)&&(!filters.priority||t.priority===filters.priority));return `${pageHeader('Paso a paso','La jornada de hoy',user.role==='admin'?'Aquí puedes acompañar cada preparación sin perder de vista a las personas.':'Todo lo que necesitas está ordenado en el momento correcto.',user.role==='admin'?button({label:'Abrir Motor de Producción',iconName:'spark',attrs:'data-route="productionEngine"'}):'')}<section class="filters" aria-label="Elige qué preparaciones quieres ver">${user.role==='admin'?`<label class="field"><span>Ver a</span><select data-filter="assignee"><option value="">Todo el equipo</option>${USERS.filter(u=>u.role==='production').map(u=>`<option value="${u.id}" ${filters.assignee===u.id?'selected':''}>${u.name}</option>`).join('')}</select></label>`:''}<label class="field"><span>Momento del día</span><select data-filter="shift"><option value="">Toda la jornada</option>${Object.entries(SHIFT).map(([v,l])=>`<option value="${v}" ${filters.shift===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>Cómo va</span><select data-filter="status"><option value="">Todas</option>${Object.entries(STATUS).map(([v])=>`<option value="${v}" ${filters.status===v?'selected':''}>${HUMAN_STATUS[v]}</option>`).join('')}</select></label><label class="field"><span>Nivel de atención</span><select data-filter="priority"><option value="">Cualquiera</option>${Object.entries(PRIORITY).map(([v,l])=>`<option value="${v}" ${filters.priority===v?'selected':''}>${l}</option>`).join('')}</select></label></section><section class="cards">${filtered.length?filtered.map(t=>taskCard(t,user.role==='admin')).join(''):emptyState('Aquí no hay nada por ahora','Prueba mirando otro momento o estado de la jornada.')}</section>`}

const phaseTypeLabel={preparation:'Preparación',cooking:'Cocción',cooling:'Enfriado',resting:'Reposo',decoration:'Decoración',packing:'Empaque'};
const resourceLabel={oven:'Horno',stove:'Cocina',passive:'Espera',worker:'Trabajo manual'};
const durationLabel=minutes=>minutes>=60?`${Math.floor(minutes/60)} h ${minutes%60?`${minutes%60} min`:''}`.trim():`${minutes} min`;
function productionEngineView(user){if(user.role!=='admin')return permissionDenied();const plan=buildProductionPlan(productionPhases),productionById=id=>DEMO_PRODUCTIONS.find(item=>item.id===id),parallelProductions=[...new Set(plan.parallelPairs.flat().map(item=>productionById(item.productionId)?.name).filter(Boolean))];return `${pageHeader('Plan inteligente','Motor de Producción','Un orden sugerido para avanzar con calma, aprovechar las esperas y cuidar cada dependencia.',button({label:'Volver a la jornada',variant:'tertiary',attrs:'data-route="board"'}))}<section class="engine-summary"><article class="metric"><span class="metric-icon">${icon('production',17)}</span><span>Producciones del día</span><strong>${DEMO_PRODUCTIONS.length}</strong><small>${productionPhases.length} momentos coordinados</small></article><article class="metric"><span class="metric-icon">${icon('clock',17)}</span><span>Tiempo total</span><strong>${durationLabel(plan.totalMinutes)}</strong><small>desde las ${formatClock(0,plan)}</small></article><article class="metric"><span class="metric-icon">${icon('check',17)}</span><span>Finalización estimada</span><strong>${formatClock(plan.finishMinute,plan)}</strong><small>si comenzamos a tiempo</small></article><article class="metric"><span class="metric-icon">${icon('alert',17)}</span><span>Cuello de botella</span><strong>${plan.bottleneck?.resource==='oven'?'Horno':resourceLabel[plan.bottleneck?.resource]||'Sin conflictos'}</strong><small>${plan.bottleneck?`${plan.bottleneck.minutes} min de uso`:'Todo fluye'}</small></article></section><section class="miski-engine card"><span class="miski-orb">✦</span><div><span class="eyebrow">Sugerencia de Miski</span><h2>${esc(plan.suggestions[0])}</h2><p>${esc(plan.suggestions.slice(1).join(' '))}</p></div></section><section class="engine-layout"><article class="panel engine-timeline"><div class="engine-section-head"><div><span class="eyebrow">Orden sugerido</span><h2>Línea de tiempo</h2></div><span class="chip">${formatClock(0,plan)} — ${formatClock(plan.finishMinute,plan)}</span></div><div class="timeline-list">${plan.timeline.map((phase,index)=>{const production=productionById(phase.productionId),blocked=blockedBy(phase,productionPhases),canStart=canStartPhase(productionPhases.find(item=>item.id===phase.id),productionPhases),running=productionPhases.find(item=>item.id===phase.id)?.status==='in_progress',completed=productionPhases.find(item=>item.id===phase.id)?.status==='completed';return `<article class="timeline-item ${completed?'is-completed':running?'is-running':blocked.length?'is-blocked':''}"><div class="timeline-time"><strong>${formatClock(phase.startMinute,plan)}</strong><span>${durationLabel(phase.durationMinutes)}</span></div><span class="timeline-dot"></span><div class="timeline-content"><div class="timeline-title"><div><span class="eyebrow">${esc(production?.name)} · ${phaseTypeLabel[phase.type]||phase.type}</span><h3>${esc(phase.name)}</h3></div>${statusChip(completed?'completed':running?'in_progress':blocked.length?'paused':'ready',completed?'Completada':running?'En marcha':blocked.length?'En espera':'Lista')}</div><div class="timeline-meta"><span>${icon('clock',15)} ${formatClock(phase.startMinute,plan)}–${formatClock(phase.endMinute,plan)}</span><span>${icon('production',15)} ${resourceLabel[phase.resource]||phase.resource}</span>${blocked.length?`<span>${icon('lock',15)} Espera: ${esc(blocked.map(item=>item.name).join(', '))}</span>`:''}</div><div class="timeline-actions">${running?button({label:'Marcar como lista',variant:'secondary',iconName:'check',attrs:`data-engine-complete="${phase.id}"`}):completed?'':button({label:blocked.length?'Esperando dependencia':'Comenzar',variant:canStart?'primary':'disabled',iconName:blocked.length?'lock':'play',attrs:`data-engine-start="${phase.id}" ${canStart?'':'disabled'}`})}</div></div></article>`}).join('')}</div></article><aside class="engine-insights"><article class="panel"><span class="eyebrow">Podemos avanzar en paralelo</span><h2>${parallelProductions.length} producciones coordinadas</h2><p>${parallelProductions.length?`${parallelProductions.join(', ')} comparten la jornada sin bloquearse todo el tiempo.`:'Hoy conviene trabajar de forma secuencial.'}</p></article><article class="panel"><span class="eyebrow">Esperas aprovechables</span><h2>${plan.waits.length} momentos</h2><p>Los enfriados y reposos liberan al equipo para avanzar con otras preparaciones.</p></article><article class="panel"><span class="eyebrow">Conflictos</span><h2>${plan.conflicts.length?'Necesitan revisión':'Todo está conectado'}</h2><p>${plan.conflicts.length?`${plan.conflicts.length} dependencias no pudieron resolverse.`:'No encontramos ciclos ni dependencias perdidas en este plan.'}</p></article><article class="panel engine-note"><span class="eyebrow">Prototipo local</span><p>Este orden utiliza datos simulados. Cuando exista la base privada, el motor recibirá recetas versionadas, disponibilidad del equipo y recursos reales.</p></article></aside></section>`}

const movementTime=value=>new Intl.DateTimeFormat('es-PE',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(value));
const stockTone=item=>item.stock<=0?'critical':item.stock<item.minimumStock?'warning':'healthy';
const money=value=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN',maximumFractionDigits:0}).format(value);
function managementView(user){if(user.role!=='admin')return permissionDenied();const cost=abcCost(DEMO_COST_COMPONENTS),cash=[7,30,90].map(days=>cashProjection(DEMO_CASH_MOVEMENTS,days)),kpis=managementKpis({sales:DEMO_SALES,...DEMO_MANAGEMENT_CONTEXT}),purchases=purchaseRecommendations(DEMO_INVENTORY_ITEMS,inventoryEvents),best=[...DEMO_SALES].sort((a,b)=>b.units-a.units)[0],least=[...DEMO_SALES].sort((a,b)=>a.margin/a.amount-b.margin/b.amount)[0];return `${pageHeader('Decisiones con contexto','Vista Gerencial','Una lectura breve de lo que importa hoy.',button({label:'Volver al inventario',variant:'tertiary',attrs:'data-route="inventory"'}))}<section class="management-kpis"><article class="metric"><span>Ventas del día</span><strong>${money(kpis.salesToday)}</strong><small>datos demostrativos</small></article><article class="metric"><span>Rentabilidad</span><strong>${kpis.margin.toFixed(1)}%</strong><small>margen de contribución</small></article><article class="metric"><span>Merma</span><strong>${kpis.wasteRate.toFixed(1)}%</strong><small>sobre consumo registrado</small></article><article class="metric"><span>Tiempo perdido</span><strong>${kpis.lostMinutes} min</strong><small>esperas operativas</small></article><article class="metric"><span>Productividad</span><strong>${kpis.productivity.toFixed(0)}%</strong><small>órdenes completadas</small></article><article class="metric"><span>Uso del horno</span><strong>${kpis.ovenUtilization.toFixed(0)}%</strong><small>del turno disponible</small></article></section><section class="management-layout"><div class="management-main"><article class="panel abc-card"><div class="inventory-table-head"><div><span class="eyebrow">Costeo ABC</span><h2>Brownies · OP demostrativa</h2></div><strong>${money(cost.total)}</strong></div><div class="abc-breakdown">${DEMO_COST_COMPONENTS.map(item=>`<div><span>${esc(item.label)}</span><strong>${money(item.amount)}</strong><small>${item.driver==='material'?'Costo directo':'Actividad · '+item.driver.replace('_',' ')}</small></div>`).join('')}</div><footer><span>Costo por lote <strong>${money(cost.total)}</strong></span><span>Costo unitario <strong>${money(cost.unitCost)}</strong></span></footer></article><article class="panel cash-card"><div class="inventory-table-head"><div><span class="eyebrow">Flujo de caja</span><h2>Proyección</h2></div><span class="chip">Sin conexión bancaria</span></div><div class="cash-horizons">${cash.map(item=>`<div><span>${item.days} días</span><strong class="${item.net<0?'negative':'positive'}">${money(item.net)}</strong><small>${money(item.inflows)} entradas · ${money(item.outflows)} salidas</small></div>`).join('')}</div><div class="cash-pending"><span><strong>${DEMO_CASH_MOVEMENTS.filter(item=>item.direction==='in'&&item.status==='pending').length}</strong> cobros pendientes</span><span><strong>${DEMO_CASH_MOVEMENTS.filter(item=>item.direction==='out'&&item.status==='pending').length}</strong> pagos pendientes</span></div></article><article class="panel product-insights"><div><span class="eyebrow">Más vendido</span><h3>${esc(best.product)}</h3><p>${best.units} unidades registradas.</p></div><div><span class="eyebrow">Menor rentabilidad</span><h3>${esc(least.product)}</h3><p>${(least.margin/least.amount*100).toFixed(1)}% de margen.</p></div></article></div><aside class="management-side"><article class="panel purchase-card"><span class="eyebrow">Compras inteligentes</span><h2>Comprar con anticipación</h2>${purchases.length?purchases.slice(0,3).map(item=>`<div class="purchase-recommendation">${icon('clock',16)}<p>${esc(item.message)}</p></div>`).join(''):'<p class="muted">No hay compras urgentes.</p>'}<small>Miski recomienda; nunca compra automáticamente.</small></article><article class="panel miski-chat"><div class="miski-chat-head"><span class="miski-orb">✦</span><div><span class="eyebrow">Asistente gerencial</span><h2>Pregunta a Miski</h2></div></div><div class="miski-messages">${miskiMessages.slice(-5).map(item=>`<p class="${item.role}">${esc(item.text)}</p>`).join('')}</div><form id="miskiManagementForm"><label><span class="sr-only">Pregunta para Miski</span><input name="message" placeholder="¿Cómo estará el horno hoy?" autocomplete="off"></label>${button({label:'Preguntar',iconName:'arrow',type:'submit'})}</form><small>Respuestas locales con datos de demostración.</small></article><article class="panel architecture-note"><span class="eyebrow">Arquitectura desacoplada</span><p>Los indicadores consumen proyecciones de eventos. No escriben en recetas, órdenes ni inventario.</p></article></aside></section>`}
function inventoryView(user){if(user.role!=='admin')return permissionDenied();const all=projectInventory(DEMO_INVENTORY_ITEMS,inventoryEvents),items=inventoryType?all.filter(item=>item.type===inventoryType):all,alerts=inventoryAlerts(DEMO_INVENTORY_ITEMS,inventoryEvents),wip=all.filter(item=>item.type==='work_in_progress'),fudgeBatch=DEMO_INTERMEDIATE_BATCHES[0],fudgeVariance=yieldVariance(fudgeBatch.expectedYield,fudgeBatch.actualYield);return `${pageHeader('Calculado desde movimientos','Inventario Inteligente','Tú registras lo que ocurrió. Le Miski OS mantiene el stock.',`<div class="header-actions-inline">${button({label:'Registrar evento',iconName:'plus',attrs:'data-route="inventoryEvent"'})}${button({label:'Volver a órdenes',variant:'tertiary',attrs:'data-route="productionOrders"'})}</div>`)}<section class="inventory-principle">${icon('spark',20)}<div><strong>El inventario no se edita.</strong><p>Cada compra, producción, consumo, merma, ajuste o transferencia deja un movimiento trazable.</p></div><span class="chip">Cálculo automático</span></section><section class="inventory-summary"><article class="metric"><span>Elementos</span><strong>${all.length}</strong><small>en seis inventarios</small></article><article class="metric"><span>Alertas activas</span><strong>${alerts.length}</strong><small>priorizadas por Miski</small></article><article class="metric"><span>Productos en proceso</span><strong>${wip.length}</strong><small>con lote y vencimiento</small></article><article class="metric"><span>Movimientos</span><strong>${inventoryEvents.length}</strong><small>eventos locales</small></article></section><section class="miski-engine inventory-miski"><span class="miski-orb">✦</span><div><span class="eyebrow">Miski recomienda</span><h2>Queda fudge suficiente para aproximadamente 9 cuchareables.</h2><p>La ganache vence pronto; conviene incorporarla en la producción programada.</p></div></section><div class="inventory-tabs" aria-label="Tipos de inventario"><button class="category-pill ${!inventoryType?'active':''}" data-inventory-type="">Todo</button>${Object.entries(INVENTORY_TYPES).map(([id,label])=>`<button class="category-pill ${inventoryType===id?'active':''}" data-inventory-type="${id}">${esc(label)}</button>`).join('')}</div><section class="inventory-layout"><div><div class="inventory-table-head"><div><span class="eyebrow">Stock proyectado</span><h2>${inventoryType?INVENTORY_TYPES[inventoryType]:'Todos los elementos'}</h2></div><small>${items.length} registros</small></div><div class="inventory-list">${items.map(item=>`<article class="inventory-item"><div class="inventory-item-title"><span class="stock-indicator ${stockTone(item)}"></span><div><span class="eyebrow">${esc(INVENTORY_TYPES[item.type])}</span><h3>${esc(item.name)}</h3></div></div><div><small>Stock actual</small><strong>${item.stock} ${esc(item.unit)}</strong></div><div><small>Mínimo / ideal</small><strong>${item.minimumStock} / ${item.idealStock} ${esc(item.unit)}</strong></div><div><small>Último movimiento</small><strong>${item.lastMovement?`${EVENT_TYPES[item.lastMovement.type]} · ${movementTime(item.lastMovement.occurredAt)}`:'Sin movimientos'}</strong></div><div><small>Próximo vencimiento</small><strong>${item.nextExpiry||'No aplica'}</strong></div></article>`).join('')}</div></div><aside class="inventory-side"><article class="panel inventory-alerts"><span class="eyebrow">Atención sugerida</span><h2>Alertas automáticas</h2><div>${alerts.map(alert=>`<p class="inventory-alert ${alert.level}">${icon(alert.level==='critical'?'alert':'clock',15)}<span>${esc(alert.message)}</span></p>`).join('')||'<p>Todo se encuentra dentro de los niveles esperados.</p>'}</div></article><article class="panel yield-card"><span class="eyebrow">Rendimiento del último lote</span><h2>Fudge</h2><div><span>Esperado<strong>${fudgeVariance.expected} g</strong></span><span>Real<strong>${fudgeVariance.actual} g</strong></span><span>Diferencia<strong>${fudgeVariance.difference} g</strong></span><span>Variación<strong>${fudgeVariance.percentage.toFixed(1)}%</strong></span></div><small>${esc(fudgeBatch.formulaVersion)} · ${esc(fudgeBatch.responsible)}</small></article></aside></section><section class="panel movement-ledger"><div class="inventory-table-head"><div><span class="eyebrow">Trazabilidad local</span><h2>Últimos movimientos</h2></div></div>${inventoryEvents.slice().reverse().slice(0,6).map(event=>{const item=DEMO_INVENTORY_ITEMS.find(value=>value.id===event.itemId);return `<div class="movement-row"><span class="chip">${esc(EVENT_TYPES[event.type])}</span><strong>${esc(item?.name)}</strong><span class="movement-quantity ${event.quantityDelta<0?'negative':'positive'}">${event.quantityDelta>0?'+':''}${event.quantityDelta} ${esc(event.unit)}</span><small>${movementTime(event.occurredAt)} · ${esc(event.responsible||'Sistema')}</small></div>`}).join('')}</section>`}
function inventoryEventView(user){if(user.role!=='admin')return permissionDenied();return `${pageHeader('Nuevo movimiento','Registrar un evento','Describe lo que ocurrió; el stock se recalculará automáticamente.',button({label:'Cancelar',variant:'tertiary',attrs:'data-route="inventory"'}))}<section class="inventory-event-layout"><form id="inventoryEventForm" class="panel inventory-event-form"><span class="eyebrow">Movimiento local</span><h2>¿Qué ocurrió?</h2><label class="field"><span>Tipo de evento</span><select name="eventType" required>${Object.entries(EVENT_TYPES).map(([id,label])=>`<option value="${id}">${esc(label)}</option>`).join('')}</select></label><label class="field"><span>Elemento</span><select name="itemId" required>${DEMO_INVENTORY_ITEMS.map(item=>`<option value="${item.id}">${esc(item.name)} · ${esc(INVENTORY_TYPES[item.type])}</option>`).join('')}</select></label><label class="field"><span>Cantidad registrada</span><input name="quantity" type="number" min="0" step="0.01" value="1" required></label><label class="field"><span>Nota</span><textarea name="note" placeholder="Ej. recepción del proveedor o consumo de la OP"></textarea></label><p class="form-helper">Compras y producciones suman. Consumos y mermas descuentan. Las transferencias conservan el total general.</p>${button({label:'Registrar y recalcular',iconName:'check',type:'submit'})}</form><aside class="panel inventory-event-help"><span class="miski-orb">✦</span><span class="eyebrow">Miski cuida la trazabilidad</span><h2>No estás corrigiendo una cifra.</h2><p>Estás dejando constancia de un hecho. El sistema conservará el evento y volverá a calcular el saldo completo.</p><div class="event-types-list">${Object.values(EVENT_TYPES).map(label=>`<span>${icon('check',14)} ${esc(label)}</span>`).join('')}</div></aside></section>`}

const orderPriorityLabel=value=>({high:'Alta',normal:'Normal',urgent:'Urgente',low:'Baja'}[value]||value);
const quantityLabel=value=>`${value.value} ${value.unit}`;
function productionOrderCard(order){const status=orderStatus(order.status);return `<article class="order-card"><div class="order-card-head"><div><span class="eyebrow">${esc(order.code)}</span><h2>${esc(order.formula.name)}</h2></div>${statusChip(order.status==='completed'?'completed':order.status==='pending'?'pending':'in_progress',status?.label)}</div><div class="order-card-meta"><span>${icon('calendar',15)} ${esc(order.date)}</span><span>${icon('user',15)} ${esc(order.responsible.name)}</span><span>${icon('production',15)} ${esc(quantityLabel(order.requestedQuantity))}</span></div><div class="order-card-progress">${progressBar(orderProgress(order.status))}<small>${orderProgress(order.status)}% del recorrido</small></div>${button({label:'Abrir orden',variant:'secondary',iconName:'arrow',attrs:`data-production-order="${order.id}"`})}</article>`}
function productionOrdersView(user){if(user.role!=='admin')return permissionDenied();const active=productionOrders.filter(order=>order.status!=='completed').length;return `${pageHeader('Operación del día','Órdenes de Producción','Cada lote conserva su propia ejecución sin alterar la Fórmula Maestra.',`<div class="header-actions-inline">${button({label:'Motor de Producción',variant:'tertiary',attrs:'data-route="productionEngine"'})}</div>`)}<section class="orders-summary"><article class="metric"><span>Total</span><strong>${productionOrders.length}</strong><small>órdenes demostrativas</small></article><article class="metric"><span>En recorrido</span><strong>${active}</strong><small>requieren seguimiento</small></article><article class="metric"><span>Terminadas</span><strong>${productionOrders.length-active}</strong><small>listas para cierre</small></article></section><section class="order-grid">${productionOrders.map(productionOrderCard).join('')}</section><aside class="order-local-note">${icon('lock',18)}<p><strong>Prototipo local.</strong> Estas órdenes usan referencias y cantidades de demostración; no contienen fórmulas ni se guardan en una base pública.</p></aside>`}
function orderRecommendation(order){if(order.status==='in_preparation')return 'Mientras termina el pesado, puedes dejar el horno listo para recibir la primera bandeja.';if(order.status==='in_oven')return 'El horno está ocupado. Aprovecha este momento para preparar el área de enfriado.';if(order.status==='resting')return 'Mientras el lote reposa, puedes avanzar con otra preparación sin interrumpir su recorrido.';if(order.status==='completed')return 'Excelente trabajo. Esta orden completó todo su recorrido.';return `La producción terminaría aproximadamente a las ${order.timeline.at(-1)?.time||'hora prevista'}.`}
function productionOrderDetail(user){if(user.role!=='admin')return permissionDenied();const order=productionOrders.find(item=>item.id===selectedProductionOrder);if(!order)return emptyState('Orden no disponible','Vuelve a la lista para elegir una orden de producción.');const status=orderStatus(order.status),next=nextOrderStatus(order.status),checklist=currentChecklist(order),ready=canAdvanceOrder(order);return `${pageHeader('Orden de Producción',order.code,`${order.formula.name} · Lote de ${quantityLabel(order.requestedQuantity)}`,button({label:'Volver a órdenes',variant:'tertiary',attrs:'data-route="productionOrders"'}))}<section class="formula-snapshot"><div>${icon('lock',18)}<div><span class="eyebrow">Fórmula Maestra · solo referencia</span><strong>${esc(order.formula.internalCode)} · versión ${order.formula.versionNumber}</strong><p>Esta versión queda fijada para la orden y nunca se modifica desde aquí.</p></div></div><span class="chip">Referencia inmutable</span></section><section class="order-progress" aria-label="Progreso de la orden">${ORDER_STATUSES.map((item,index)=>{const currentIndex=ORDER_STATUSES.findIndex(value=>value.id===order.status);return `<div class="order-progress-step ${index<currentIndex?'is-done':index===currentIndex?'is-current':''}"><span>${index<currentIndex?'✓':index+1}</span><small>${esc(item.label)}</small></div>`}).join('')}</section><section class="order-detail-grid"><div class="order-main"><article class="panel order-facts"><div><small>Estado actual</small><strong>${esc(status?.label)}</strong></div><div><small>Responsable</small><strong>${esc(order.responsible.name)}</strong></div><div><small>Prioridad</small><strong>${esc(orderPriorityLabel(order.priority))}</strong></div><div><small>Fecha</small><strong>${esc(order.date)}</strong></div><div><small>Cantidad solicitada</small><strong>${esc(quantityLabel(order.requestedQuantity))}</strong></div><div><small>Rendimiento esperado</small><strong>${esc(quantityLabel(order.expectedYield))}</strong></div></article><article class="panel order-checklist"><div class="engine-section-head"><div><span class="eyebrow">Etapa actual</span><h2>${esc(status?.label)}</h2></div><span class="chip">${checklist.filter(item=>item.checked).length}/${checklist.length}</span></div><div class="checklist-items">${checklist.map(item=>`<label class="checklist-item ${item.checked?'is-checked':''}"><input type="checkbox" data-order-check="${item.id}" ${item.checked?'checked':''}><span>${esc(item.label)}</span></label>`).join('')}</div><div class="checklist-footer"><p>${ready?(next?`Todo listo para continuar a ${next.label}.`:'La orden está completa.'):'Completa la verificación de esta etapa para continuar.'}</p>${next?button({label:`Continuar a ${next.label}`,variant:ready?'primary':'disabled',iconName:'arrow',attrs:`data-order-advance ${ready?'':'disabled'}`}):'<span class="completion-seal">✓ Orden terminada</span>'}</div></article></div><aside class="order-side"><article class="miski-engine order-miski"><span class="miski-orb">✦</span><div><span class="eyebrow">Miski recomienda</span><h2>${esc(orderRecommendation(order))}</h2></div></article><article class="panel order-timeline"><span class="eyebrow">Recorrido previsto</span><h2>Línea de tiempo</h2><ol>${order.timeline.map((event,index)=>`<li class="${index<order.history.length?'is-done':''}"><time>${esc(event.time)}</time><span></span><strong>${esc(event.label)}</strong></li>`).join('')}</ol></article></aside></section>`}

function recipeCard(recipe){return `<article class="recipe-card"><div class="recipe-photo"><img src="${recipe.photo}" alt="Fotografía referencial de ${esc(recipe.name)}" loading="lazy"><span class="demo-ribbon session-ribbon">${esc(recipe.status)} · v${recipe.versionNumber}</span></div><div class="recipe-card-body"><div class="recipe-card-top"><span class="eyebrow">${esc(recipe.category)}</span><span class="chip">Privada</span></div><h3>${esc(recipe.name)}</h3><div class="recipe-facts"><span>${icon('production',16)}<small>Rendimiento</small><strong>${esc(recipe.yield)}</strong></span><span>${icon('clock',16)}<small>Tiempo estimado</small><strong>${recipe.estimatedMinutes?`${recipe.estimatedMinutes} min`:'Por revisar'}</strong></span></div><div class="task-actions">${button({label:'Abrir ficha',variant:'secondary',iconName:'arrow',attrs:`data-recipe="${recipe.id}"`})}${recipe.status==='DRAFT'?button({label:'Enviar a revisión',variant:'tertiary',attrs:`data-recipe-status="REVIEWED" data-recipe-id="${recipe.id}"`}):recipe.status==='REVIEWED'?button({label:'Aprobar',attrs:`data-recipe-status="APPROVED" data-recipe-id="${recipe.id}"`}):button({label:'Nueva versión',variant:'tertiary',attrs:`data-recipe-version="${recipe.id}"`})}</div></div></article>`}
function recipeLibrary(user){if(!can(user,'recipes'))return permissionDenied();const recipes=recipeRepository.list({search:recipeSearch,category:recipeCategory}),categories=recipeRepository.categories();return `${pageHeader('Biblioteca privada','Recetas de Le Miski','Un espacio preparado para cuidar y organizar el conocimiento de la casa.',button({label:'Importar recetas',iconName:'plus',attrs:'data-route="recipeImport"'}))}<section class="recipe-security">${icon('lock',22)}<div><strong>Vista reservada para Marisol</strong><p>Las fichas demostrativas son públicas. Los documentos que importes se procesan solo en la memoria de esta sesión y desaparecen al recargar.</p></div><span class="security-state">Procesamiento local</span></section><form class="recipe-search" id="recipeSearchForm" role="search"><label><span class="sr-only">Buscar una receta</span>${icon('search')}<input name="recipeSearch" value="${esc(recipeSearch)}" placeholder="Busca por nombre o categoría" autocomplete="off"></label>${button({label:'Buscar',variant:'secondary',type:'submit'})}</form><div class="recipe-categories" aria-label="Categorías de recetas"><button class="category-pill ${!recipeCategory?'active':''}" data-recipe-category="">Todas</button>${categories.map(category=>`<button class="category-pill ${recipeCategory===category?'active':''}" data-recipe-category="${esc(category)}">${esc(category)}</button>`).join('')}</div><div class="recipe-results-head"><p><strong>${recipes.length}</strong> ${plural(recipes.length,'ficha disponible','fichas disponibles')}</p><small>${recipeCategory||'Todas las categorías'}</small></div><section class="recipe-grid">${recipes.length?recipes.map(recipeCard).join(''):emptyState('No encontramos esa receta','Prueba con otro nombre o vuelve a mirar todas las categorías.','search')}</section>`}

function recipeImport(user){if(!can(user,'recipes','import'))return permissionDenied();return `${pageHeader('Importación privada','Traigamos tus recetas con cuidado','El documento se analizará en este dispositivo. Nada se enviará ni se guardará de forma permanente.',button({label:'Volver al recetario',variant:'tertiary',attrs:'data-route="recipes"'}))}<section class="import-layout"><article class="panel import-drop"><span class="import-mark">${icon('book',30)}</span><span class="eyebrow">Archivo Word</span><h2>Selecciona tu recetario</h2><p>Usaremos títulos, secciones y patrones de cantidades para proponer una estructura editable.</p><label class="file-picker ${importBusy?'is-loading':''}"><input type="file" accept=".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document" data-recipe-docx ${importBusy?'disabled':''}><span>${importBusy?'Analizando el documento…':'Elegir archivo .docx'}</span></label><small>Máximo 15 MB · El archivo permanece en este dispositivo.</small></article><aside class="panel import-explainer"><span class="eyebrow">Antes de incorporar</span><h2>Tú conservas el control</h2><ol><li>Detectaremos las recetas y sus secciones.</li><li>Podrás corregir cada dato interpretado.</li><li>Mostraremos lo que necesita revisión.</li><li>Solo incorporarás las fichas que selecciones.</li></ol><div class="alert">${icon('alert')}<span>Esta etapa es temporal. No uses esta sesión como respaldo definitivo de tus fórmulas.</span></div></aside></section>`}

const importValue=value=>value??'';
function ingredientRows(recipe){return recipe.ingredients.map((item,index)=>`<div class="ingredient-row"><label class="field"><span>Ingrediente ${index+1}</span><input data-import-field="ingredient-name" data-item-index="${index}" value="${esc(item.name)}"></label><label class="field compact"><span>Cantidad</span><input type="number" step="any" data-import-field="ingredient-quantity" data-item-index="${index}" value="${importValue(item.quantity)}"></label><label class="field compact"><span>Unidad</span><input data-import-field="ingredient-unit" data-item-index="${index}" value="${esc(importValue(item.unit))}"></label><label class="field ingredient-note"><span>Nota de preparación</span><input data-import-field="ingredient-preparation-note" data-item-index="${index}" value="${esc(importValue(item.preparationNote))}" placeholder="Ej. tamizada o a temperatura ambiente"></label><label class="optional-ingredient"><input type="checkbox" data-import-field="ingredient-optional" data-item-index="${index}" ${item.optional?'checked':''}> Opcional</label><button class="icon-button remove-import-item" data-remove-ingredient="${index}" aria-label="Quitar ${esc(item.name)}">${icon('close')}</button></div>`).join('')}
function stepRows(recipe){return recipe.steps.map((step,index)=>`<div class="step-row"><span>${index+1}</span><label class="field"><span class="sr-only">Paso ${index+1}</span><textarea data-import-field="step-instruction" data-item-index="${index}">${esc(step.instruction)}</textarea></label><button class="icon-button remove-import-item" data-remove-step="${index}" aria-label="Quitar paso ${index+1}">${icon('close')}</button></div>`).join('')}
function recipeReview(user){if(!can(user,'recipes','import'))return permissionDenied();if(!importedDrafts.length)return recipeImport(user);const recipe=importedDrafts[selectedImportIndex],selectedCount=importedDrafts.filter(x=>x._selected).length;return `${pageHeader('Revisión antes de importar',`${importedDrafts.length} ${plural(importedDrafts.length,'receta detectada','recetas detectadas')}`,'Nada se incorporará hasta que confirmes.',button({label:'Cancelar',variant:'tertiary',attrs:'data-cancel-import'}))}<section class="import-review"><aside class="import-recipe-list panel"><div class="import-list-head"><span class="eyebrow">Encontramos</span><strong>${selectedCount} seleccionadas</strong></div>${importedDrafts.map((item,index)=>`<button class="import-recipe-option ${index===selectedImportIndex?'active':''}" data-import-recipe="${index}"><input type="checkbox" ${item._selected?'checked':''} tabindex="-1" aria-hidden="true"><span><strong>${esc(item.name)}</strong><small>${esc(item.category)} · ${item.warnings.length} ${plural(item.warnings.length,'aviso','avisos')}</small></span></button>`).join('')}<div class="import-list-actions">${button({label:`Importar ${selectedCount}`,iconName:'check',attrs:'data-confirm-import',variant:selectedCount?'primary':'disabled'})}</div></aside><form class="panel import-editor" id="recipeReviewForm"><div class="editor-heading"><div><span class="eyebrow">Ficha ${selectedImportIndex+1} de ${importedDrafts.length}</span><h2>${esc(recipe.name)}</h2></div><label class="select-recipe"><input type="checkbox" data-select-import ${recipe._selected?'checked':''}> Incluir esta receta</label></div>${recipe.warnings.length?`<div class="import-warnings">${icon('alert')}<div><strong>Hay ${recipe.warnings.length} ${plural(recipe.warnings.length,'detalle por revisar','detalles por revisar')}</strong><ul>${recipe.warnings.slice(0,8).map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div></div>`:''}<div class="form-grid"><label class="field"><span>Nombre</span><input data-import-field="name" value="${esc(recipe.name)}" required></label><label class="field"><span>Categoría</span><input data-import-field="category" value="${esc(recipe.category)}" required></label><label class="field"><span>Subcategoría</span><input data-import-field="subcategory" value="${esc(importValue(recipe.subcategory))}"></label><label class="field"><span>Tiempo total (minutos)</span><input type="number" min="0" data-import-field="totalTimeMinutes" value="${importValue(recipe.totalTimeMinutes)}"></label><label class="field"><span>Rendimiento</span><input type="number" step="any" min="0" data-import-field="yield-quantity" value="${importValue(recipe.yield.quantity)}"></label><label class="field"><span>Unidad del rendimiento</span><input data-import-field="yield-unit" value="${esc(importValue(recipe.yield.unit))}"></label><label class="field full"><span>Descripción</span><textarea data-import-field="description">${esc(recipe.description||'')}</textarea></label></div><div class="editor-section"><div><span class="eyebrow">Ingredientes</span><h3>${recipe.ingredients.length} detectados</h3></div>${ingredientRows(recipe)}${button({label:'Agregar ingrediente',variant:'secondary',iconName:'plus',attrs:'data-add-ingredient'})}</div><div class="editor-section"><div><span class="eyebrow">Preparación</span><h3>${recipe.steps.length} pasos detectados</h3></div>${stepRows(recipe)}${button({label:'Agregar paso',variant:'secondary',iconName:'plus',attrs:'data-add-step'})}</div></form></section>`}
function sessionRecipeDetail(recipe){const yieldText=[recipe.yield?.quantity,recipe.yield?.unit].filter(Boolean).join(' ')||'Por revisar';return `${pageHeader('Importación temporal',esc(recipe.name),`${esc(recipe.category)} · Disponible solo durante esta sesión`,button({label:'Volver al recetario',variant:'tertiary',attrs:'data-route="recipes"'}))}<section class="recipe-security">${icon('alert',22)}<div><strong>Esta receta todavía no está almacenada</strong><p>Se conserva únicamente en la memoria de esta pestaña. Recargar o cerrar eliminará la información importada.</p></div><span class="security-state">Sesión actual</span></section><section class="session-recipe-detail"><article class="panel"><span class="eyebrow">Ficha estructurada</span><h2>${esc(recipe.name)}</h2>${recipe.description?`<p>${esc(recipe.description)}</p>`:''}<div class="recipe-detail-facts"><div><small>Categoría</small><strong>${esc(recipe.category)}</strong></div><div><small>Rendimiento</small><strong>${esc(yieldText)}</strong></div><div><small>Tiempo total</small><strong>${recipe.totalTimeMinutes?`${recipe.totalTimeMinutes} minutos`:'Por revisar'}</strong></div><div><small>Estado</small><strong>Revisada en esta sesión</strong></div></div></article><article class="panel"><span class="eyebrow">Ingredientes</span><h2>${recipe.ingredients.length} ${plural(recipe.ingredients.length,'ingrediente','ingredientes')}</h2><div class="structured-list">${recipe.ingredients.map(item=>`<div><span>${esc([item.quantity,item.unit].filter(Boolean).join(' ')||'—')}</span><strong>${esc(item.name)}</strong></div>`).join('')}</div></article><article class="panel"><span class="eyebrow">Preparación</span><h2>${recipe.steps.length} ${plural(recipe.steps.length,'paso','pasos')}</h2><ol class="structured-steps">${recipe.steps.map(step=>`<li>${esc(step.instruction)}</li>`).join('')}</ol></article></section>`}
function recipeDetail(user){if(!can(user,'recipes'))return permissionDenied();const recipe=recipeRepository.getById(selectedRecipe);if(!recipe)return emptyState('Esta ficha no está disponible','Vuelve al recetario para elegir otra preparación.','book');if(recipeRepository.isSessionRecipe(recipe.id))return sessionRecipeDetail(recipe);return `${pageHeader('Ficha privada',esc(recipe.name),`${esc(recipe.category)} · Información de demostración`,button({label:'Volver al recetario',variant:'tertiary',attrs:'data-route="recipes"'}))}<section class="recipe-detail"><div class="recipe-detail-visual"><img src="${recipe.photo}" alt="Fotografía demostrativa de ${esc(recipe.name)}"><span>📸 Fotografía de demostración</span></div><div class="recipe-detail-main"><div class="recipe-private-label">${icon('lock',17)} Solo Marisol</div><span class="eyebrow">📋 Información general</span><h2>${esc(recipe.name)}</h2><p>Esta ficha muestra únicamente datos demostrativos seguros. El conocimiento privado permanece bloqueado.</p><div class="recipe-detail-facts"><div><small>⭐ Dificultad</small><strong>Intermedia</strong></div>
<div><small>⏱ Tiempo</small><strong>${recipe.estimatedMinutes} min</strong></div>
<div><small>⚖ Rendimiento</small><strong>${esc(recipe.yield)}</strong></div>
<div><small>👩‍🍳 Responsable</small><strong>Marisol</strong></div><div><small>Categoría</small><strong>${esc(recipe.category)}</strong></div><div><small>Estado</small><strong>${esc(recipe.status)} · v${recipe.versionNumber}</strong></div></div></div></section>${recipeEditorialPanel(recipe)}
<section class="private-recipe-heading"><span class="eyebrow">Conocimiento protegido</span><h2>Contenido privado de la receta</h2><p>Estas áreas se conectarán únicamente cuando exista autenticación y almacenamiento privado.</p></section><section class="locked-sections recipe-private-sections"><article><span class="locked-emoji">🧈</span><div><span class="eyebrow">Ingredientes</span><h3>Bloqueado</h3><p>Fórmula y cantidades disponibles solo desde la futura fuente privada.</p></div>${icon('lock')}</article><article><span class="locked-emoji">🥣</span><div><span class="eyebrow">Procedimiento</span><h3>Bloqueado</h3><p>Los pasos de elaboración requieren permisos sobre la receta completa.</p></div>${icon('lock')}</article><article><span class="locked-emoji">📸</span><div><span class="eyebrow">Fotografías de referencia</span><h3>Bloqueado</h3><p>Las imágenes técnicas vivirán en almacenamiento privado.</p></div>${icon('lock')}</article><article><span class="locked-emoji">🎥</span><div><span class="eyebrow">Video de referencia</span><h3>Bloqueado</h3><p>El material audiovisual se entregará mediante acceso temporal.</p></div>${icon('lock')}</article><article><span class="locked-emoji">🌡</span><div><span class="eyebrow">Temperaturas críticas</span><h3>Bloqueado</h3><p>Los controles técnicos formarán parte de la versión privada.</p></div>${icon('lock')}</article><article><span class="locked-emoji">⚠</span><div><span class="eyebrow">Puntos críticos de calidad</span><h3>Bloqueado</h3><p>Los criterios de calidad aparecerán según el rol de cada persona.</p></div>${icon('lock')}</article>
<article><span class="locked-emoji">💰</span><div><span class="eyebrow">Costos</span><h3>Bloqueado</h3><p>La información financiera tendrá permisos administrativos separados.</p></div>${icon('lock')}</article><article><span class="locked-emoji">🚚</span><div><span class="eyebrow">Proveedores</span><h3>Bloqueado</h3><p>Los datos comerciales no se incluirán en archivos públicos.</p></div>${icon('lock')}</article>
<article><span class="locked-emoji">📝</span><div><span class="eyebrow">Notas de Marisol</span><h3>Bloqueado</h3><p>Las observaciones personales permanecerán reservadas para Marisol.</p></div>${icon('lock')}</article></section><section class="future-connection"><span class="miski-orb">✦</span><div><span class="eyebrow">Preparada para el futuro</span><h2>La estructura ya está lista.</h2><p>Cuando conectemos la base privada, cada área recibirá únicamente la información permitida sin rehacer la ficha.</p></div></section>`}
function permissionDenied(){return `<section class="permission-denied">${icon('lock',28)}<span class="eyebrow">Espacio privado</span><h1>Este recetario está reservado para Marisol.</h1><p>Tu jornada seguirá mostrando únicamente la información necesaria para realizar tus preparaciones.</p>${button({label:'Volver a hoy',attrs:'data-route="home"'})}</section>`}

function detail(t,user){const canOperate=user.role==='production'&&t.assigneeId===user.id,running=t.status==='in_progress',paused=t.status==='paused',done=t.status==='completed',next=store.get().tasks.filter(x=>x.assigneeId===t.assigneeId&&x.status!=='completed'&&x.id!==t.id).sort((a,b)=>a.plannedTime.localeCompare(b.plannedTime))[0];const guidance=done?'Esta preparación ya está lista.':!t.timing.startedAt?'Lee la indicación con calma. Cuando estés lista, comenzamos.':paused?'Tómate el tiempo que necesites. Reanudamos cuando estés lista.':running?'Concéntrate en esta preparación. Nosotros cuidamos el tiempo.':'Revisemos juntas esta preparación.';return `${pageHeader('Ahora mismo',esc(t.preparation),guidance,button({label:'Volver a la jornada',variant:'tertiary',attrs:'data-route="board"'}))}${done?`<section class="completion-note"><span class="completion-mark">${icon('check',26)}</span><div><span class="eyebrow">Excelente trabajo</span><h2>${next?`Lo siguiente será ${esc(next.preparation)}.`:'Has terminado todo lo de hoy.'}</h2><p>${next?'Cuando estés lista, puedes continuar con la siguiente preparación.':'Gracias por cuidar cada detalle.'}</p></div>${next?button({label:'Ver lo que sigue',iconName:'arrow',attrs:`data-task="${next.id}"`}):button({label:'Ver cómo fue mi día',variant:'secondary',attrs:'data-route="summary"'})}</section>`:''}${t.incident.reported?`<div class="incident-box">${icon('alert')}<div><b>Hay algo que merece atención</b><p>${esc(t.incident.description||'El equipo dejó una nota para revisar juntas.')}</p></div></div>`:''}<section class="detail-grid"><div class="panel focus-panel"><span class="eyebrow">${done?'Tiempo que dedicamos':'Te acompañamos con el tiempo'}</span><div class="timer ${running?'is-running':''}" data-timer="${t.id}">${formatDuration(elapsedMs(t))}</div><div class="task-actions primary-moment">${canOperate&&!t.timing.startedAt?button({label:'Comenzar',variant:'success',iconName:'play',attrs:'data-action="start"'}):''}${canOperate&&running?button({label:'Hacer una pausa',variant:'secondary',iconName:'pause',attrs:'data-action="pause"'}):''}${canOperate&&(paused||t.status==='incident')&&t.timing.pausedAt?button({label:'Continuar',variant:'success',iconName:'play',attrs:'data-action="resume"'}):''}${canOperate&&!done&&t.timing.startedAt?button({label:'Ya está lista',iconName:'check',attrs:'data-action="finish"'}):''}${canOperate&&!done?button({label:'Necesito ayuda',variant:'tertiary',iconName:'alert',attrs:'data-action="incident"'}):''}</div>${user.role==='admin'?`<label class="field" style="margin-top:1.2rem"><span>¿Cómo va esta preparación?</span><select data-admin-status>${Object.entries(STATUS).map(([v])=>`<option value="${v}" ${t.status===v?'selected':''}>${HUMAN_STATUS[v]}</option>`).join('')}</select></label>`:''}<div class="detail-list"><div><small>Comenzamos a las</small><b>${esc(t.plannedTime)}</b></div><div><small>Reservamos</small><b>${t.expectedMinutes} minutos</b></div><div><small>Comenzó realmente</small><b>${clock(t.timing.startedAt)}</b></div><div><small>Quedó lista</small><b>${clock(t.timing.finishedAt)}</b></div><div><small>Tiempo de pausa</small><b>${Math.round(t.timing.totalPausedMs/60000)} min</b></div><div><small>Vamos a preparar</small><b>${esc(t.quantity)}</b></div></div><div class="instructions"><span class="eyebrow">Ten presente</span><p>${esc(t.instructions)}</p></div></div><aside class="panel"><span class="eyebrow">Lo que buscamos</span><h2>Una buena preparación</h2><div class="detail-list"><div><small>Esperamos obtener</small><b>${t.expectedYield.value} ${esc(t.expectedYield.unit)}</b></div><div><small>Obtuvimos</small><b>${t.actualYield.value??'—'} ${esc(t.actualYield.unit)}</b></div><div><small>Lo que no usamos</small><b>${esc(t.waste||'—')}</b></div><div><small>Tiempo dedicado</small><b>${actualMinutes(t)} min</b></div></div>${t.notes?`<p><b>Lo que aprendimos</b><br>${esc(t.notes)}</p>`:''}<label class="field"><span>Una foto para recordar el resultado</span><input type="file" accept="image/*" capture="environment" data-photo><small class="field-hint">Es opcional. Puedes tomarla directamente desde este dispositivo.</small></label>${t.photo?`<img class="photo-preview" src="${t.photo}" alt="Resultado de ${esc(t.preparation)}">`:''}</aside></section>`}

function summary(tasks,user){const visible=user.role==='admin'?tasks:tasks.filter(t=>t.assigneeId===user.id),m=metrics(visible),compliance=m.total?Math.round(m.completed/m.total*100):0;const reflection=m.completed===m.total&&m.total?'Lo logramos. Todo lo que planeamos quedó listo.':m.completed?`Completamos ${m.completed} ${plural(m.completed,'preparación','preparaciones')}. Aún podemos continuar con calma.`:'La jornada recién comienza. Cada preparación tendrá su momento.';return `${pageHeader('Una pausa para mirar','¿Cómo fue nuestra jornada?',reflection)}${miskiPrompt()}<section class="summary-story card"><span class="eyebrow">Lo más importante</span><h2>${compliance}% de lo planeado está listo.</h2><p>${m.incidents?`Hay ${m.incidents} ${plural(m.incidents,'situación que nos dejó un aprendizaje','situaciones que nos dejaron aprendizajes')}.`:'El equipo avanzó sin situaciones que requieran atención.'}</p>${progressBar(compliance,'Preparaciones completadas')}</section><section class="summary-grid">${[['Habíamos preparado el día para',`${m.total} ${plural(m.total,'preparación','preparaciones')}`],['Ya podemos celebrar',`${m.completed} ${plural(m.completed,'lista','listas')}`],['Nos esperan todavía',`${m.pending} ${plural(m.pending,'preparación','preparaciones')}`],['Tiempo que reservamos',`${m.expectedMinutes} min`],['Tiempo que dedicamos',`${m.actualMinutes} min`],['Esperábamos obtener',m.expectedYield],['Logramos obtener',m.actualYield],['Momentos para aprender',m.incidents],['Cumplimos',`${compliance}%`]].map(x=>`<article class="summary-block"><span>${x[0]}</span><strong>${x[1]}</strong></article>`).join('')}</section>`}
function more(){return `${pageHeader('Tu espacio','Todo lo demás está aquí','Opciones sencillas para sentirte cómoda durante la jornada.')}<section class="panel"><span class="eyebrow">Volver a empezar</span><h2>Recuperar el día de demostración</h2><p class="muted">Si quieres practicar nuevamente, podemos dejar las cuatro preparaciones como estaban al principio.</p>${button({label:'Preparar la demostración otra vez',variant:'danger',iconName:'reset',attrs:'data-reset'})}<div style="height:1px;background:var(--line);margin:2rem 0"></div><span class="eyebrow">Seguridad de tu cuenta</span><h2>Tu acceso está protegido</h2><p>La contraseña se actualiza directamente en Supabase y nunca se guarda en Le Miski OS.</p><div class="form-actions">${button({label:'Cambiar contraseña',variant:'secondary',attrs:'data-change-password'})}${button({label:'Cerrar sesión',variant:'tertiary',iconName:'logout',attrs:'data-logout'})}</div></section>`}

function render(){if(!authReady){app.innerHTML=`<main class="access" id="main-content"><section class="access-panel"><span class="eyebrow">Le Miski OS</span><h1>Estamos preparando tu espacio…</h1><p class="muted">Validando tu acceso con cuidado.</p></section></main>`;return}const state=store.get(),user=sessionUser;if(!user){app.innerHTML=access();bind();return}let content;if(route==='create'&&user.role==='admin')content=createView();else if(route==='board')content=board(state.tasks,user);else if(route==='productionEngine')content=productionEngineView(user);else if(route==='productionOrders')content=productionOrdersView(user);else if(route==='productionOrderDetail')content=productionOrderDetail(user);else if(route==='inventory')content=connectedInventoryView(user);else if(route==='inventoryEvent')content=connectedInventoryEventView(user);else if(route==='management')content=managementView(user);else if(route==='recipes'&&can(user,'recipes'))content=recipeLibrary(user);else if(route==='recipeDetail'&&can(user,'recipes'))content=recipeDetail(user);else if(route==='recipeImport'&&can(user,'recipes'))content=recipeImport(user);else if(route==='recipeReview'&&can(user,'recipes'))content=recipeReview(user);else if(route==='summary')content=summary(state.tasks,user);else if(route==='more')content=more();else if(route==='detail'){const t=state.tasks.find(x=>x.id===selectedTask);content=t?detail(t,user):emptyState('Tarea no disponible','La tarea seleccionada ya no existe.')}else content=user.role==='admin'?adminHome(state.tasks):workerHome(user,state.tasks);app.innerHTML=shell(content,user);bind()}

function bind(){document.querySelector('#authForm')?.addEventListener('submit',handleSignIn);document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>go(b.dataset.route));document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>go('detail',b.dataset.task));document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=async()=>{selectedRecipe=b.dataset.recipe;route='recipeDetail';render();try{await recipeRepository.loadDetail(selectedRecipe);render()}catch(error){showToast(error.message||'No pudimos abrir esta receta.','error')}});document.querySelectorAll('[data-production-order]').forEach(b=>b.onclick=()=>{selectedProductionOrder=b.dataset.productionOrder;go('productionOrderDetail')});document.querySelectorAll('[data-order-check]').forEach(input=>input.onchange=()=>toggleOrderCheck(input.dataset.orderCheck,input.checked));document.querySelector('[data-order-advance]')?.addEventListener('click',advanceSelectedOrder);document.querySelectorAll('[data-recipe-category]').forEach(b=>b.onclick=()=>{recipeCategory=b.dataset.recipeCategory;render()});document.querySelector('#recipeSearchForm')?.addEventListener('submit',e=>{e.preventDefault();recipeSearch=new FormData(e.currentTarget).get('recipeSearch')?.trim()||'';render()});document.querySelectorAll('[data-logout]').forEach(b=>b.onclick=handleSignOut);document.querySelectorAll('[data-filter]').forEach(x=>x.onchange=()=>{filters[x.dataset.filter]=x.value;render()});document.querySelector('[data-admin-status]')?.addEventListener('change',e=>{store.updateTask(selectedTask,{status:e.target.value,progress:e.target.value==='completed'?100:store.get().tasks.find(t=>t.id===selectedTask)?.progress||0});showToast('Estado actualizado');render()});document.querySelector('[data-reset]')?.addEventListener('click',confirmReset);document.querySelector('#taskForm')?.addEventListener('submit',createTask);document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-engine-start]').forEach(b=>b.onclick=()=>startEnginePhase(b.dataset.engineStart));document.querySelectorAll('[data-engine-complete]').forEach(b=>b.onclick=()=>completeEnginePhase(b.dataset.engineComplete));bindRecipeImport()}

async function handleSignIn(event){event.preventDefault();if(authBusy)return;const form=new FormData(event.currentTarget);authBusy=true;authMessage='';render();try{sessionUser=await signIn(String(form.get('email')).trim(),String(form.get('password')));store.selectUser(sessionUser.id);route='home'}catch(error){sessionUser=null;store.logout();authMessage=error?.message==='Invalid login credentials'?'El correo o la contraseña no coinciden. Inténtalo nuevamente.':error?.message||'No pudimos validar tu acceso.'}finally{authBusy=false;render()}}
async function handleSignOut(){try{await signOut()}catch(error){showToast(error.message||'No pudimos cerrar la sesión.','error');return}sessionUser=null;store.logout();route='home';render()}
function forgotPasswordNotice(){openModal({title:'Recuperación por correo',description:'Este flujo está preparado y se activará cuando configuremos la URL definitiva de Vercel.',confirmLabel:'Entendido',body:'<div class="alert">'+icon('alert')+'<span>Por ahora, solicita el cambio a Marisol desde una sesión autenticada. No enviaremos un enlace local que pueda fallar.</span></div>'})}
function changePasswordModal(){openModal({title:'Cambiar contraseña',description:'La nueva contraseña se enviará directamente a Supabase Auth. Le Miski OS no la guarda.',confirmLabel:'Guardar nueva contraseña',body:'<div class="form-grid"><label class="field full"><span>Nueva contraseña</span><input type="password" autocomplete="new-password" minlength="12" data-new-password required></label><label class="field full"><span>Repite la nueva contraseña</span><input type="password" autocomplete="new-password" minlength="12" data-confirm-password required></label></div><p class="field-hint">Usa al menos 12 caracteres y no reutilices una contraseña de otro servicio.</p>',onConfirm:async root=>{const password=root.querySelector('[data-new-password]').value,confirmation=root.querySelector('[data-confirm-password]').value;if(password.length<12){showToast('La contraseña debe tener al menos 12 caracteres.','error');return false}if(password!==confirmation){showToast('Las contraseñas no coinciden.','error');return false}try{await updatePassword(password);showToast('Tu contraseña fue actualizada de forma segura.');return true}catch(error){showToast(error.message||'No pudimos actualizar la contraseña.','error');return false}}})}

app.addEventListener('click',event=>{if(event.target.closest('[data-change-password]'))changePasswordModal();if(event.target.closest('[data-forgot-password]'))forgotPasswordNotice()});
app.addEventListener('click',async event=>{const manualButton=event.target.closest('[data-manual-recipe]'),statusButton=event.target.closest('[data-recipe-status]'),versionButton=event.target.closest('[data-recipe-version]');if(manualButton){importedDrafts=[{id:uid(),name:'Nueva receta',category:'Sin categoría',description:'',yield:{quantity:undefined,unit:'',notes:''},ingredients:[],steps:[],totalTimeMinutes:undefined,temperature:{value:undefined,unit:'C',notes:''},criticalPoints:[],source:{type:'manual',fileName:'',importedAt:new Date().toISOString()},status:'draft',warnings:[],_selected:true}];selectedImportIndex=0;route='recipeReview';render();return}if(statusButton){statusButton.disabled=true;try{await recipeRepository.setStatus(statusButton.dataset.recipeId,statusButton.dataset.recipeStatus);showToast(statusButton.dataset.recipeStatus==='APPROVED'?'La versión quedó aprobada.':'La receta está lista para revisión.');render()}catch(error){showToast(error.message||'No pudimos cambiar el estado.','error')}return}if(versionButton){versionButton.disabled=true;try{const current=await recipeRepository.loadDetail(versionButton.dataset.recipeVersion);await recipeRepository.saveDrafts([{...current,id:current.id,source:{type:'manual'}}]);showToast('Creamos una nueva versión en borrador.');render()}catch(error){showToast(error.message||'No pudimos crear la versión.','error')}}});

function toggleOrderCheck(itemId,checked){const order=productionOrders.find(item=>item.id===selectedProductionOrder),item=order&&currentChecklist(order).find(entry=>entry.id===itemId);if(!item)return;item.checked=checked;render()}
function advanceSelectedOrder(){const order=productionOrders.find(item=>item.id===selectedProductionOrder);if(!order)return;if(!advanceOrder(order)){showToast('Completa la verificación de esta etapa antes de continuar.','error');return}showToast(`La orden avanzó a ${orderStatus(order.status)?.label}.`);render()}

function startEnginePhase(id){const phase=productionPhases.find(item=>item.id===id);if(!phase)return;if(!canStartPhase(phase,productionPhases)){const waiting=blockedBy(phase,productionPhases);showToast(`Primero debe terminar ${waiting[0]?.name||'la preparación anterior'}.`,'error');return}phase.status='in_progress';showToast(`Comenzamos: ${phase.name}.`);render()}
function completeEnginePhase(id){const phase=productionPhases.find(item=>item.id===id);if(!phase||phase.status!=='in_progress')return;phase.status='completed';showToast(`${phase.name} quedó lista. Veamos qué sigue.`);render()}

function bindRecipeImport(){document.querySelector('[data-recipe-docx]')?.addEventListener('change',analyzeRecipeDocument);document.querySelectorAll('[data-import-recipe]').forEach(button=>button.onclick=()=>{selectedImportIndex=Number(button.dataset.importRecipe);render()});document.querySelector('[data-select-import]')?.addEventListener('change',e=>{importedDrafts[selectedImportIndex]._selected=e.target.checked;render()});document.querySelectorAll('[data-import-field]').forEach(input=>input.addEventListener(input.type==='checkbox'?'change':'input',updateImportedField));document.querySelectorAll('[data-remove-ingredient]').forEach(button=>button.onclick=()=>{importedDrafts[selectedImportIndex].ingredients.splice(Number(button.dataset.removeIngredient),1);render()});document.querySelectorAll('[data-remove-step]').forEach(button=>button.onclick=()=>{importedDrafts[selectedImportIndex].steps.splice(Number(button.dataset.removeStep),1);importedDrafts[selectedImportIndex].steps.forEach((step,index)=>step.order=index+1);render()});document.querySelector('[data-add-ingredient]')?.addEventListener('click',()=>{importedDrafts[selectedImportIndex].ingredients.push({id:uid(),name:'',quantity:undefined,unit:'',preparationNote:'',section:'',optional:false,rawText:''});render()});document.querySelector('[data-add-step]')?.addEventListener('click',()=>{const recipe=importedDrafts[selectedImportIndex];recipe.steps.push({id:uid(),order:recipe.steps.length+1,instruction:'',notes:''});render()});document.querySelector('[data-cancel-import]')?.addEventListener('click',()=>{importedDrafts=[];go('recipes')});document.querySelector('[data-confirm-import]')?.addEventListener('click',confirmRecipeImport)}

async function analyzeRecipeDocument(e){const file=e.target.files?.[0];if(!file)return;importBusy=true;render();try{const blocks=await readDocx(file);importedDrafts=parseRecipeBlocks(blocks,file.name).map(recipe=>({...recipe,_selected:true}));selectedImportIndex=0;route='recipeReview';showToast(`Encontramos ${importedDrafts.length} ${plural(importedDrafts.length,'receta','recetas')}.`)}catch(error){showToast(error.message||'No pudimos analizar este documento.','error')}finally{importBusy=false;render()}}
function updateImportedField(e){const recipe=importedDrafts[selectedImportIndex],field=e.target.dataset.importField,index=Number(e.target.dataset.itemIndex),value=e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?(e.target.value===''?undefined:Number(e.target.value)):e.target.value;if(field==='yield-quantity')recipe.yield.quantity=value;else if(field==='yield-unit')recipe.yield.unit=value;else if(field==='ingredient-name')recipe.ingredients[index].name=value;else if(field==='ingredient-quantity')recipe.ingredients[index].quantity=value;else if(field==='ingredient-unit')recipe.ingredients[index].unit=value;else if(field==='ingredient-preparation-note')recipe.ingredients[index].preparationNote=value;else if(field==='ingredient-optional')recipe.ingredients[index].optional=value;else if(field==='step-instruction')recipe.steps[index].instruction=value;else recipe[field]=value;if(field==='name')document.querySelector('.editor-heading h2').textContent=recipe.name}
async function confirmRecipeImport(){const selected=importedDrafts.filter(recipe=>recipe._selected).map(({_selected,warnings,...recipe})=>({...recipe,status:'DRAFT'}));if(!selected.length){showToast('Selecciona al menos una receta.','error');return}try{await recipeRepository.saveDrafts(selected);const count=selected.length;importedDrafts=[];recipeSearch='';recipeCategory='';showToast(`${count} ${plural(count,'receta quedó guardada','recetas quedaron guardadas')} como borrador privado.`);go('recipes')}catch(error){showToast(error.message||'No pudimos guardar los borradores.','error')}}

function createTask(e){e.preventDefault();const submit=e.currentTarget.querySelector('[type="submit"]');submit.classList.add('is-loading');submit.disabled=true;const f=new FormData(e.currentTarget),assignee=userById(f.get('assigneeId'));if(!assignee){submit.classList.remove('is-loading');submit.disabled=false;return}const at=new Date().toISOString();store.addTask({id:uid(),preparation:f.get('preparation').trim(),assigneeId:assignee.id,shift:f.get('shift'),quantity:f.get('quantity').trim(),plannedTime:f.get('plannedTime'),expectedMinutes:Number(f.get('expectedMinutes')),expectedYield:{value:Number(f.get('expectedValue')),unit:f.get('unit')},priority:f.get('priority'),instructions:f.get('instructions').trim(),status:f.get('status'),progress:f.get('status')==='completed'?100:0,timing:{startedAt:null,finishedAt:null,pausedAt:null,totalPausedMs:0},actualYield:{value:null,unit:f.get('unit')},waste:'',notes:'',incident:{reported:false,description:'',createdAt:null},photo:null,createdAt:at,updatedAt:at});showToast(`${assignee.name} ya puede verla en su jornada.`);go('board')}
function action(kind){const t=store.get().tasks.find(x=>x.id===selectedTask);if(!t)return;const now=new Date().toISOString();if(kind==='start'){store.updateTask(t.id,{status:'in_progress',progress:10,timing:{...t.timing,startedAt:now}});showToast(`Comenzamos con ${t.preparation}.`)}if(kind==='pause'){store.updateTask(t.id,{status:'paused',progress:Math.max(20,t.progress),timing:{...t.timing,pausedAt:now}});showToast('Tómate el tiempo que necesites.','warning')}if(kind==='resume'){const extra=t.timing.pausedAt?Date.now()-new Date(t.timing.pausedAt).getTime():0;store.updateTask(t.id,{status:'in_progress',progress:Math.max(35,t.progress),timing:{...t.timing,pausedAt:null,totalPausedMs:t.timing.totalPausedMs+extra}});showToast('Seguimos juntas.')}if(kind==='incident')incidentModal(t);if(kind==='finish')finishModal(t);if(!['incident','finish'].includes(kind))render()}
function incidentModal(t){openModal({title:'¿Qué necesitas contarnos?',description:`Puedes dejar una nota sobre ${esc(t.preparation)}. Marisol la verá para acompañarte.`,confirmLabel:'Compartir con Marisol',variant:'danger',body:`<label class="field"><span>Cuéntanos qué ocurrió</span><textarea data-incident-description maxlength="240" required placeholder="Escribe lo necesario, con tus propias palabras"></textarea><small class="field-hint">No tienes que resolverlo sola. Guardaremos esta nota con la preparación.</small></label>`,onConfirm:root=>{const value=root.querySelector('[data-incident-description]').value.trim();if(!value){root.querySelector('textarea').focus();return false}store.updateTask(t.id,{status:t.status==='completed'?'completed':'incident',incident:{reported:true,description:value,createdAt:new Date().toISOString()}});showToast('Gracias por contarlo. Marisol podrá verlo.','warning');render()}})}
function finishModal(t){openModal({title:'¿Cómo salió esta preparación?',description:`Antes de continuar, guardemos el resultado de ${esc(t.preparation)}.`,confirmLabel:'Guardar y continuar',body:`<div class="finish-encouragement">${icon('spark',20)}<p>Lo importante es registrar lo que ocurrió con claridad. Cada resultado nos ayuda a trabajar mejor mañana.</p></div><div class="form-grid"><label class="field"><span>¿Cuánto logramos obtener? (${esc(t.expectedYield.unit)})</span><input data-finish-yield type="number" min="0" step="0.01" value="${t.actualYield.value??''}" required></label><label class="field"><span>¿Hubo algo que no usamos?</span><input data-finish-waste value="${esc(t.waste)}" placeholder="Ej. 120 g o 0"></label><label class="field full"><span>¿Hay algo que quieras recordar?</span><textarea data-finish-notes maxlength="300" placeholder="Textura, presentación o algo que aprendiste">${esc(t.notes)}</textarea></label></div>`,onConfirm:root=>{const input=root.querySelector('[data-finish-yield]'),value=Number(input.value);if(input.value===''||!Number.isFinite(value)||value<0){input.focus();return false}let paused=t.timing.totalPausedMs;if(t.timing.pausedAt)paused+=Date.now()-new Date(t.timing.pausedAt).getTime();store.updateTask(t.id,{status:'completed',progress:100,timing:{...t.timing,finishedAt:new Date().toISOString(),pausedAt:null,totalPausedMs:paused},actualYield:{value,unit:t.expectedYield.unit},waste:root.querySelector('[data-finish-waste]').value.trim(),notes:root.querySelector('[data-finish-notes]').value.trim()});showToast('Excelente trabajo. Esta preparación está lista.');render()}})}
function confirmReset(){openModal({title:'¿Volvemos a preparar la demostración?',description:'Dejaremos las cuatro preparaciones como estaban al comienzo para que puedas practicar otra vez.',confirmLabel:'Sí, volver al comienzo',variant:'danger',body:'<div class="alert">'+icon('alert')+'<span>Lo que registraste durante esta práctica dejará de aparecer en este dispositivo.</span></div>',onConfirm:()=>{store.reset();route='home';showToast('Todo está listo para comenzar de nuevo.');render()}})}

document.addEventListener('change',e=>{if(e.target.matches('[type=file][data-photo]')){const file=e.target.files?.[0];if(!file)return;if(file.size>900000){showToast('Esta foto es un poco grande. Prueba con una más ligera.','error');e.target.value='';return}const reader=new FileReader();reader.onload=()=>{store.updateTask(selectedTask,{photo:reader.result});showToast('La foto quedó guardada con esta preparación.');render()};reader.readAsDataURL(file)}});
const localBoardView=board;
board=(tasks,user)=>localBoardView(tasks,user).replace('Abrir Motor de Producción','Órdenes de producción').replace('data-route="productionEngine"','data-route="productionOrders"');
productionOrdersView=connectedProductionOrdersView;
productionOrderDetail=connectedProductionOrderDetail;
render();
authenticatedUser().then(user=>{sessionUser=user;if(user)store.selectUser(user.id);else store.logout()}).catch(error=>{console.error('No pudimos recuperar la sesión.',error);sessionUser=null;store.logout();authMessage='No pudimos validar tu sesión. Vuelve a ingresar.'}).finally(()=>{authReady=true;render()});
setInterval(()=>{document.querySelectorAll('[data-timer]').forEach(el=>{const t=store.get().tasks.find(x=>x.id===el.dataset.timer);if(t)el.textContent=formatDuration(elapsedMs(t))})},1000);
setInterval(()=>{document.querySelectorAll('[data-op-started-at][data-op-running="true"]').forEach(el=>{const elapsed=Math.max(0,Date.now()-new Date(el.dataset.opStartedAt).getTime());el.textContent=formatDuration(elapsed)})},1000);
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
function connectedInventoryView(user){if(user.role!=='admin')return permissionDenied();if(!inventoryRepository.loaded)return emptyState('Cargando inventario privado','Estamos consultando movimientos y saldos seguros.','clock');return inventoryDashboard(inventoryRepository,{filter:inventoryType,icon,button})}
function connectedInventoryEventView(user){if(user.role!=='admin')return permissionDenied();if(!inventoryRepository.loaded)return emptyState('Cargando inventario privado','Estamos preparando el formulario seguro.','clock');return inventoryMovementForm(inventoryRepository,{button})}
function connectedProductionOrdersView(user){if(user.role!=='admin')return permissionDenied();if(!productionOrderRepository.loaded)return emptyState('Cargando órdenes privadas','Estamos consultando la ejecución operativa.','clock');return productionOrderList(productionOrderRepository,{button})}
function connectedProductionOrderDetail(user){if(user.role!=='admin')return permissionDenied();const order=productionOrderRepository.getById(selectedProductionOrder);if(!order)return emptyState('Cargando la OP','Estamos reuniendo su ejecución y movimientos.','clock');return liveProductionOrderDetail(order,{button})}

async function openManjarProductionOrder(){
  try{
    if(!productionOrderRepository.loaded)await productionOrderRepository.load();
    const order=productionOrderRepository.orders.find(value=>['OP-DEMO-MAN-001','OP-DEMO-MANJAR-001'].includes(value.code));
    if(!order)throw new Error('La OP demostrativa de Manjar no está disponible.');
    selectedProductionOrder=order.id;
    route='productionOrderDetail';
    await productionOrderRepository.loadDetail(order.id);
    render();
    scrollTo({top:0,behavior:'smooth'});
  }catch(error){
    showToast(error.message||'No pudimos abrir la preparación.','error');
  }
}

function ensureManjarProductionCta(){
  if(route!=='detail'||selectedTask!=='demo-manjar'||sessionUser?.role!=='admin')return;
  const target=document.querySelector('.detail-grid aside');
  if(!target||target.querySelector('[data-open-manjar-op]'))return;
  const action=document.createElement('button');
  action.type='button';
  action.className='button button-primary manjar-production-cta';
  action.dataset.openManjarOp='true';
  action.textContent='Iniciar preparación';
  action.addEventListener('click',openManjarProductionOrder);
  target.append(action);
}

new MutationObserver(ensureManjarProductionCta).observe(app,{childList:true,subtree:true});
ensureManjarProductionCta();
